#include <Arduino.h>

/*
  Basic TCRT5000 Sensor Test

  This sketch reads the digital output of a TCRT5000 IR sensor module.
  It's used to verify that the sensor is working and to see the raw
  digital signal (HIGH/LOW or 1/0) before we build the pulse counting logic.

  WIRING:
  - ESP32 3.3V -> TCRT5000 VCC
  - ESP32 GND  -> TCRT5000 GND
  - ESP32 GPIO 23 -> TCRT5000 D0 (Digital Out)

  NOTE: We use GPIO 23, but you can change this to any other suitable GPIO pin.
  Just make sure to update the `SENSOR_PIN` constant below.
*/

// Define the GPIO pin connected to the TCRT5000's digital output (D0)
const int SENSOR_PIN = 23;

void setup() {
  // Start serial communication for debugging
  Serial.begin(115200);

  // Wait a moment for the serial monitor to connect
  delay(1000); 

  // Set the sensor pin as an input
  pinMode(SENSOR_PIN, INPUT);

  Serial.println("TCRT5000 Sensor Test Initialized");
  Serial.println("---------------------------------");
  Serial.print("Reading from GPIO: ");
  Serial.println(SENSOR_PIN);
  Serial.println("---------------------------------");
  Serial.println("You should see '1' (idle) and '0' (triggered) or vice-versa.");
}

void loop() {
  // Read the digital value from the sensor
  int sensorValue = digitalRead(SENSOR_PIN);

  // Print the value to the serial monitor
  Serial.println(sensorValue);

  // A short delay to make the output readable
  delay(250);
}

